import test, { after, before } from 'node:test';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

// These instructions are generated by the OHOS patches, so the test needs the
// patched prefix. The browser and desktop builds keep the original text.
assert.ok(process.env.OHOS_TEST_PROCESS_PREFIX, '需指定打过 OHOS 补丁的前缀');
const prefix = resolve(process.env.OHOS_TEST_PROCESS_PREFIX);
const require = createRequire(join(prefix, 'package.json'));
const load = name => import(pathToFileURL(require.resolve(name)));
const platform = Object.getOwnPropertyDescriptor(process, 'platform');
const CJK = /[\u3400-\u9fff]/;

const [{ Context }, { SystemPrompt }, { ToolRuntime }, { LocalFileSystem },
  { WorkingDirectoryService }, { ShellEnvRegistry }, { LocalBashExecutor },
  { LocalSubprocessRuntime }, { SessionProjectionRegistry },
  bash, search, office, skill] = await Promise.all([
  ...['cordis', 'dsh-system-prompt', 'dsh-tools', 'dsh-fs-local', 'dsh-working-directory',
    'dsh-shell-env', 'dsh-bash-local', 'dsh-subprocess-local', 'dsh-session-projection']
    .map(name => load('@deepseek-ai/' + name)),
  load('@deepseek-ai/dsh-tool-bash'),
  load('@deepseek-ai/dsh-tool-fs-search'),
  load('@deepseek-ai/dsh-office-to-pdf'),
  load('@deepseek-ai/dsh-skill-office'),
]);

before(() => Object.defineProperty(process, 'platform', { ...platform, value: 'openharmony' }));
after(() => Object.defineProperty(process, 'platform', platform));

async function withLanguage(language, work) {
  const previous = process.env.DSH_APP_LANGUAGE;
  if (language === undefined) delete process.env.DSH_APP_LANGUAGE;
  else process.env.DSH_APP_LANGUAGE = language;
  try {
    return await work();
  } finally {
    if (previous === undefined) delete process.env.DSH_APP_LANGUAGE;
    else process.env.DSH_APP_LANGUAGE = previous;
  }
}

async function bashDescription() {
  const ctx = new Context();
  try {
    await ctx.plugin(SystemPrompt, {});
    await ctx.plugin(ToolRuntime, {});
    await ctx.plugin(SessionProjectionRegistry);
    await ctx.plugin(LocalFileSystem, { cwd: process.cwd() });
    await ctx.plugin(WorkingDirectoryService, { defaultDirectory: process.cwd() });
    await ctx.plugin(ShellEnvRegistry, { dshHome: process.cwd() });
    await ctx.plugin(LocalSubprocessRuntime);
    ctx.subprocess.capabilities = { kind: 'virtual', commands: ['ls', 'cat'], streamingOutput: true };
    await ctx.plugin(LocalBashExecutor, { cwd: process.cwd() });
    await ctx.plugin(bash, { enableRunInBackground: false, promoteOnTimeout: false });
    return ctx.tools.get('bash').description;
  } finally {
    await ctx.fiber.dispose();
  }
}

function grepDescription() {
  let definition;
  search.applyGrepTool({
    systemPrompt: { section() {}, getSectionOrder() { return 0; } },
    tools: { get() {}, register(value) { definition = value; } },
    on() {}, effect() {},
  }, { maxMatches: 100, maxLineBytes: 1000, maxMetaBytes: 1000, rawOutputMaxBytes: 1000,
    graceMs: 10, stderrMaxBytes: 1000, timeoutMs: 1000 });
  return definition.description;
}

async function officeFailure() {
  try {
    await office.OfficeToPdf.prototype.convertBytes.call({}, Buffer.from('x'), 'docx',
      new AbortController().signal);
  } catch (error) {
    return error.message;
  }
  throw new Error('Office conversion should refuse on OpenHarmony');
}

async function libreOfficeGuidance() {
  let provider;
  skill.apply({ skills: { registerProvider(create) { provider = create(); } } }, {});
  const locator = join(prefix, 'node_modules/@deepseek-ai/dsh-skill-office/assets/office-render/SKILL.md');
  const skillEntry = await provider.get({ name: 'office-render', locator, rank: 0 },
    { signal: new AbortController().signal });
  return skillEntry.content;
}

const ENGLISH = {
  bash: 'This device\'s local runtime uses a virtual shell. Available commands: ls, cat.',
  streaming: 'This shell delivers output after the outer statement completes',
  budget: 'at most 100000 commands',
  grep: 'does not read the global gitignore or core.excludesFile',
  office: 'does not support Office conversion',
  libreoffice: 'does not provide the LibreOffice conversion, recalculation or rendering runtime',
};
const CHINESE = {
  bash: '鸿蒙本机使用虚拟 shell',
  streaming: '当前 shell 在外层语句完成后交付输出',
  budget: '命令执行计数上限为 100000',
  grep: '鸿蒙本机不读取全局 gitignore',
  office: '鸿蒙本机不支持 Office 转换',
  libreoffice: '鸿蒙本机不提供 LibreOffice 转换、重算或渲染运行时',
};

test('OHOS virtual shell tasks carry English instructions when the app language is English', () => withLanguage('en-US', async () => {
  const bashText = await bashDescription();
  assert.ok(bashText.includes(ENGLISH.bash), bashText);
  assert.ok(bashText.includes(ENGLISH.streaming));
  assert.ok(bashText.includes(ENGLISH.budget));
  assert.doesNotMatch(bashText, CJK);
  // iOS reuses these instructions, so the English branch must stay platform
  // neutral while the Chinese branch keeps the string iOS specialization rewrites.
  assert.doesNotMatch(bashText, /HarmonyOS|OpenHarmony|鸿蒙/i);

  const grepText = grepDescription();
  assert.ok(grepText.includes(ENGLISH.grep), grepText);
  assert.doesNotMatch(grepText, CJK);
  assert.doesNotMatch(grepText, /HarmonyOS|OpenHarmony|鸿蒙/i);

  const officeText = await officeFailure();
  assert.equal(officeText, 'This device does not support Office conversion; open the original document or an existing PDF, or convert it on a computer.');

  const officeSkillText = await libreOfficeGuidance();
  assert.ok(officeSkillText.includes(ENGLISH.libreoffice), officeSkillText.slice(-300));
  assert.doesNotMatch(officeSkillText.slice(officeSkillText.indexOf('This device')), CJK);
}));

test('OHOS virtual shell tasks keep Chinese instructions for Chinese and unwired hosts', () => withLanguage('zh-CN', async () => {
  const bashText = await bashDescription();
  assert.ok(bashText.includes(CHINESE.bash), bashText);
  assert.ok(bashText.includes(CHINESE.streaming));
  assert.ok(bashText.includes(CHINESE.budget));
  assert.ok(!bashText.includes(ENGLISH.bash));

  assert.ok(grepDescription().includes(CHINESE.grep));
  assert.equal(await officeFailure(), '鸿蒙本机不支持 Office 转换；可打开原文档、已有 PDF，或连接电脑转换。');
  assert.ok((await libreOfficeGuidance()).includes(CHINESE.libreoffice));
}));

test('the language follows the same DSH_APP_LANGUAGE prefix rule as the native phone tools', async () => {
  await withLanguage(undefined, async () => assert.ok((await bashDescription()).includes(CHINESE.bash)));
  for (const value of ['en', 'EN-gb']) {
    await withLanguage(value, async () => assert.ok((await bashDescription()).includes(ENGLISH.bash), value));
  }
  for (const value of ['', 'fr-FR']) {
    await withLanguage(value, async () => assert.ok((await bashDescription()).includes(CHINESE.bash), value));
  }
});
